/// <summary>
/// Batch to create Vendor claim
/// </summary>
public class METVendClaimProcessJob extends RunBaseBatch implements BatchRetryable
{
    protected TransDate calcDate;
    protected InventSiteId siteId;

    #Define.CurrentVersion(1)
    #LOCALMACRO.CurrentList
        calcDate,
        siteId
    #ENDMACRO

}

Method.Source:
/// <summary>
/// pack method
/// </summary>
/// <returns>container</returns>
public container pack()
{
    return [#CurrentVersion,#CurrentList];
}

/// <summary>
/// unpack method
/// </summary>
/// <param name = "_packedClass">container</param>
/// <returns>boolean</returns>
public boolean unpack(container  _packedClass)
{
    Integer version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion :
            [version, #CurrentList] = _packedClass;
            break;

        default :
            return false;
    }

    return true;
}

/// <summary>
/// parm Calc date
/// </summary>
/// <param name = "_calcDate">Calculation date</param>
/// <returns>Date</returns>
public TransDate parmCalcDate(TransDate _calcDate = calcDate)
{
    calcDate = _calcDate;
    return calcDate;
}

/// <summary>
/// parm Site
/// </summary>
/// <param name = "_siteId">Site</param>
/// <returns>SiteId</returns>
public InventSiteId parmSiteId(InventSiteId _siteId = siteId)
{
    siteId = _siteId;
    return siteId;
}

/// <summary>
/// run method for the claim creation
/// </summary>
void run()
{
    #OCCRetryCount

    try
    {
        // added logic for Clain from Vendor
        METVendClaimProcessHelper   vendClaimProcessHelper = new METVendClaimProcessHelper();
        vendClaimProcessHelper.parmSiteId(this.parmSiteId());
        vendClaimProcessHelper.parmActivationDate(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
        vendClaimProcessHelper.processForItemBasePrice();
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

/// <summary>
/// runsImpersonated method
/// </summary>
/// <returns>boolean</returns>
public boolean runsImpersonated()
{
    return true;
}

/// <summary>
/// construct method
/// </summary>
/// <returns>METVendClaimProcessJob</returns>
static METVendClaimProcessJob construct()
{
    return new METVendClaimProcessJob();
}

/// <summary>
/// main method
/// </summary>
/// <param name = "args">Args</param>
static void main(Args args)
{
    METVendClaimProcessJob vendClaimProcessJob = METVendClaimProcessJob::newStandard(args);

    if (!vendClaimProcessJob.prompt())
    {
        return;
    }

    vendClaimProcessJob.runOperation();
}

/// <summary>
/// new method
/// </summary>
/// <param name = "_args">Args</param>
/// <returns>METVendClaimProcessJob</returns>
static METVendClaimProcessJob newStandard(Args _args)
{
    METVendClaimProcessJob vendClaimProcessJob = METVendClaimProcessJob::construct();
    vendClaimProcessJob.getLast();
    vendClaimProcessJob.init();

    return vendClaimProcessJob;
}

/// <summary>
/// mustGoBatch method
/// </summary>
/// <returns>boolean</returns>
public boolean mustGoBatch()
{
    return true;
}

/// <summary>
/// canRunInNewSession method
/// </summary>
/// <returns>boolean</returns>
protected boolean canRunInNewSession()
{
    return false;
}

/// <summary>
/// isRetryable method
/// </summary>
/// <returns>boolean</returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// construct method
/// </summary>
/// <param name = "_calcDate"> Calcualtion date</param>
/// <param name = "_siteId"> Site </param>
/// <param name = "_batch"> Header Batch</param>
static void contructMETVendClaimProcessTasks( TransDate _calcDate, InventSiteId _siteId, RunBaseBatch _batch = null)
{
    METVendClaimProcessJob batchTask = METVendClaimProcessJob::construct();
    batchTask.parmCalcDate(_calcDate);
    batchTask.parmSiteId(_siteId);

    if (_batch && _batch.isInBatch())
    {
        BatchHeader batchHeader = BatchHeader::construct(_batch.parmCurrentBatch().BatchJobId);
        if (batchHeader == null)
        {
            batchHeader = batchHeader::construct();
            batchHeader.parmCaption("@MET:VendorClaims");
            batchHeader.parmAlerts(NoYes::Yes, NoYes::Yes, NoYes::Yes, NoYes::Yes, NoYes::No);
            batchHeader.parmStartDateTime(DateTimeUtil::getSystemDateTime());
        }

        ttsbegin;

        batchHeader.addRuntimeTask(batchTask, _batch.parmCurrentBatch().RecId);
        batchHeader.save();

        Batch batch;
        BatchJob batchJob;
        select firstonly batchJob
        where batchJob.RecId == _batch.parmCurrentBatch().BatchJobId
            && batchJob.DataPartition == getCurrentPartition()
            && batchJob.company == curExt()
        join batch
            where batch.ClassNumber == classNum(GUPItemBasePriceUpdateValidJob)
                && batch.DataPartition == batchJob.DataPartition
                && batch.BatchJobId == batchJob.RecId;

        if (batch.RecId)
        {
            BatchConstraints constraints;
            constraints.skipAosValidation(true);
            constraints.BatchId = batchTask.batchInfo().parmBatchId();
            constraints.DependsOnBatchId = batch.RecId;
            constraints.ExpectedStatus = BatchDependencyStatus::Finished;
            constraints.insert();
            batchHeader.save();
        }

        ttscommit;
    }
    else
    {
        batchTask.runOperation();
    }
}
